templates.supx_v1:
{
  "dns": {
    "hosts": {
      "dns.google": [
        "8.8.8.8",
        "8.8.4.4"
      ],
      "dns.quad9.net": [
        "9.9.9.9",
        "149.112.112.112"
      ]
    }
  },
  "routing": {
    "rules": [
      {
        "ip": [
          "10.8.0.1"
        ],
        "type": "field",
        "outboundTag": "proxy"
      },
      {
        "type": "field",
        "network": "tcp,udp",
        "outboundTag": "proxy"
      }
    ],
    "domainStrategy": "AsIs"
  },
  "inbounds": [
    {
      "tag": "socks",
      "port": 10808,
      "listen": "127.0.0.1",
      "protocol": "socks",
      "settings": {
        "udp": true
      },
      "sniffing": {
        "enabled": true,
        "routeOnly": false,
        "destOverride": [
          "http",
          "tls"
        ]
      }
    }
  ],
  "outbounds": [
    {
      "mux": {
        "enabled": false,
        "concurrency": -1
      },
      "tag": "proxy",
      "protocol": "vmess",
      "settings": {
        "vnext": [
          {
            "port": "{{port}}",
            "users": [
              {
                "id": "5c040f1d-45db-43bd-8d46-e4950e433735",
                "level": 8,
                "security": "auto"
              }
            ],
            "address": "{{host}}"
          }
        ]
      },
      "streamSettings": {
        "network": "tcp",
        "security": "tls",
        "tcpSettings": {
          "header": {
            "type": "none"
          }
        },
        "tlsSettings": {
          "show": false,
          "serverName": "xmfhlpy.com",
          "allowInsecure": false
        }
      }
    },
    {
      "tag": "direct",
      "protocol": "freedom",
      "settings": {}
    }
  ]
}
